<template>
  <view class="page">
    <GlobalNavBar :title="boardId?'追加留言':'创建留言板'"><template #left><view class="cancel" @tap="leave">取消</view></template><template #right><view class="save" :class="{disabled:!canPublish}" @tap="publish">发布</view></template></GlobalNavBar>
    <scroll-view scroll-y class="scroll" :style="{paddingTop:topOffset+'px'}">
      <view v-if="!boardId" class="card"><label><text>留言板标题</text><input v-model="draft.title" maxlength="40" placeholder="例如：望平街的夏夜留言" /></label><text class="count">{{draft.title.length}}/40</text></view>
      <view class="card"><text class="label">写下内容</text><textarea v-model="draft.text" maxlength="1000" placeholder="分享此刻的故事、建议或邀请…"/><text class="count">{{draft.text.length}}/1000</text></view>
      <view class="card"><view class="section-head"><text>媒体</text><text>最多 9 张图，或 1 个视频</text></view><view v-if="draft.images.length" class="media-grid"><view v-for="(url,index) in draft.images" :key="url"><image :src="url" mode="aspectFill"/><view @tap="removeImage(index)">×</view></view></view><view v-if="draft.video.url" class="video-row"><video :src="draft.video.url" :poster="draft.video.poster" controls/><view @tap="draft.video={url:'',poster:''}">移除视频</view></view><view class="media-actions"><view :class="{disabled:!!draft.video.url}" @tap="chooseImages"><view class="image-icon"></view><text>添加图片</text></view><view :class="{disabled:!!draft.images.length}" @tap="chooseVideo"><view class="video-icon"></view><text>添加视频</text></view></view></view>
      <view v-if="!boardId" class="card"><view class="section-head"><text>地图位置</text><text>{{locationText}}</text></view><view class="location-preview"><view class="pin"></view><view><text>{{draft.location.address}}</text><text>{{draft.location.coordinates[1].toFixed(4)}}, {{draft.location.coordinates[0].toFixed(4)}}</text></view></view><text class="label space">位置精度</text><view class="segments"><view v-for="item in precisions" :key="item.id" :class="{active:draft.precision===item.id}" @tap="draft.precision=item.id">{{item.name}}</view></view><text class="label space">可见范围</text><view class="segments"><view v-for="item in visibilities" :key="item.id" :class="{active:draft.visibility===item.id}" @tap="draft.visibility=item.id">{{item.name}}</view></view></view>
      <view class="ar-card"><view class="ar-mark">AR</view><view><text>到店 AR 查看</text><text>能力已预留，本版本暂不申请相机权限</text></view><view class="soon">暂未开放</view></view><view class="bottom-space"></view>
    </scroll-view>
  </view>
</template>
<script setup>
import { computed, reactive, ref, watch } from 'vue';import { onLoad } from '@dcloudio/uni-app';import GlobalNavBar from '../../components/common/GlobalNavBar.vue';import { messageBoardApi } from '../../utils/api/messageBoard.js'
const topOffset=ref(68),boardId=ref('');const picked=uni.getStorageSync('MESSAGE_BOARD_PICKED_LOCATION')||{longitude:104.0668,latitude:30.5725};const draft=reactive({title:'',text:'',images:[],video:{url:'',poster:''},location:{type:'Point',coordinates:[Number(picked.longitude),Number(picked.latitude)],address:'地图选点'},precision:'exact',visibility:'public'});const precisions=[{id:'exact',name:'精确位置'},{id:'fuzzy',name:'模糊到街区'}],visibilities=[{id:'public',name:'公开'},{id:'friends',name:'仅好友'},{id:'private',name:'仅自己'}];const canPublish=computed(()=>Boolean(draft.text.trim()||draft.images.length||draft.video.url));const locationText=computed(()=>draft.precision==='exact'?'精确点位':'约 500 米范围')
onLoad(options=>{boardId.value=options.id||'';topOffset.value=uni.getStorageSync('TOP_NAV_METRICS')?.totalPx||68;if(!boardId.value){const saved=messageBoardApi.getDraft();if(saved)Object.assign(draft,saved)}});watch(draft,value=>{if(!boardId.value)messageBoardApi.saveDraft(JSON.parse(JSON.stringify(value)))},{deep:true})
function chooseImages(){if(draft.video.url)return;uni.chooseImage({count:9-draft.images.length,sizeType:['compressed'],success:r=>{draft.images.push(...r.tempFilePaths)}})}function chooseVideo(){if(draft.images.length)return;uni.chooseVideo({compressed:true,maxDuration:60,success:r=>{draft.video={url:r.tempFilePath,poster:r.thumbTempFilePath||''}}})}function removeImage(index){draft.images.splice(index,1)}function publish(){if(!canPublish.value)return uni.showToast({title:'请添加留言内容',icon:'none'});try{let board;if(boardId.value)board=messageBoardApi.addItem(boardId.value,{text:draft.text,images:draft.images,video:draft.video});else board=messageBoardApi.create({...draft,items:[{text:draft.text,images:draft.images,video:draft.video}]});uni.showToast({title:'已发布到地图',icon:'success'});setTimeout(()=>uni.redirectTo({url:`/pages/message-board-detail/index?id=${encodeURIComponent(board.id)}`}),500)}catch(e){uni.showToast({title:e.message,icon:'none'})}}function leave(){if(!canPublish.value)return uni.navigateBack();uni.showModal({title:'保留草稿？',content:'未发布的内容可在下次继续编辑。',cancelText:'放弃',confirmText:'保留',success:r=>{if(!r.confirm)messageBoardApi.clearDraft();uni.navigateBack()}})}
</script>
<style scoped>
.page{min-height:100vh;background:var(--color-page)}.scroll{height:100vh;padding:14px 14px 0;box-sizing:border-box}.cancel,.save{min-width:58px;height:42px;border-radius:13px;display:flex;align-items:center;justify-content:center;font-size:13px;font-weight:700}.cancel{color:var(--color-text-body);background:var(--color-surface-muted)}.save{color:#fff;background:var(--gradient-primary)}.save.disabled{opacity:.4}.card,.ar-card{position:relative;margin-bottom:12px;padding:16px;border-radius:16px;background:#fff;box-shadow:var(--shadow-card)}.card label>text,.label{display:block;margin-bottom:9px;font-size:14px;font-weight:800}.card input{height:48px;padding:0 12px;border-radius:13px;background:#f2f5f3;font-size:15px}.card textarea{width:100%;min-height:150px;padding:12px;border-radius:14px;background:#f2f5f3;box-sizing:border-box;font-size:15px;line-height:1.6}.count{display:block;margin-top:7px;color:#8c9693;text-align:right;font-size:10px}.section-head{display:flex;align-items:center;justify-content:space-between;margin-bottom:12px}.section-head text:first-child{font-size:14px;font-weight:800}.section-head text:last-child{color:#8c9693;font-size:10px}.media-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:7px;margin-bottom:12px}.media-grid>view{position:relative;aspect-ratio:1}.media-grid image{width:100%;height:100%;border-radius:12px}.media-grid>view>view{position:absolute;right:5px;top:5px;width:25px;height:25px;border-radius:50%;display:flex;align-items:center;justify-content:center;background:rgba(17,28,26,.72);color:#fff}.video-row video{width:100%;height:190px;border-radius:14px}.video-row>view{height:42px;margin:8px 0;display:flex;align-items:center;justify-content:center;color:#c94444}.media-actions{display:grid;grid-template-columns:1fr 1fr;gap:9px}.media-actions>view{height:74px;border-radius:14px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:8px;background:var(--color-surface-muted);color:#45504d;font-size:11px}.media-actions .disabled{opacity:.36}.image-icon{width:21px;height:17px;border:2px solid currentColor;border-radius:4px;position:relative}.image-icon:after{content:'';position:absolute;left:4px;bottom:3px;width:9px;height:7px;border-left:2px solid currentColor;border-top:2px solid currentColor;transform:rotate(45deg)}.video-icon{width:21px;height:17px;border:2px solid currentColor;border-radius:5px;position:relative}.video-icon:after{content:'';position:absolute;right:-8px;top:3px;border-left:7px solid currentColor;border-top:4px solid transparent;border-bottom:4px solid transparent}.location-preview{padding:12px;border-radius:14px;display:flex;align-items:center;gap:11px;background:#eef7f5}.pin{width:16px;height:16px;border:4px solid var(--color-primary);border-radius:50%}.location-preview text{display:block}.location-preview text:first-child{font-weight:700}.location-preview text:last-child{margin-top:4px;color:#798481;font-size:10px}.space{margin-top:16px}.segments{display:flex;gap:8px}.segments view{flex:1;min-height:44px;border-radius:13px;display:flex;align-items:center;justify-content:center;background:var(--color-surface-muted);color:#65706d;font-size:12px}.segments .active{background:var(--color-text);color:#fff}.ar-card{display:flex;align-items:center;gap:12px}.ar-mark{width:48px;height:48px;border-radius:15px;display:flex;align-items:center;justify-content:center;background:#edeffd;color:#5965b3;font-weight:850}.ar-card>view:nth-child(2){flex:1}.ar-card text{display:block}.ar-card>view text:first-child{font-weight:800}.ar-card>view text:last-child{margin-top:4px;color:#8a9491;font-size:10px}.soon{padding:8px;border-radius:10px;background:var(--color-surface-muted);color:#75807d;font-size:10px}.bottom-space{height:45px}
</style>
